INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l18','colored','coloured','有色的;美语 colored,英式 coloured') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
