INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l18','take interest in','',NULL,'/teɪk ˈɪntrəst ɪn/','People who take no interest in art still notice them.','对艺术不感兴趣的人也会注意到它们。','She takes great interest in science.','她对科学很感兴趣。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l18','on display','',NULL,'/ɑːn dɪˈspleɪ/','The sculptures were on display in the park.','那些雕塑在公园里展出。','New phones are on display in the store.','新手机在店里陈列着。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l18','attached to','',NULL,'/əˈtætʃt tə/','Wires were attached to the metal spheres.','金属丝连在金属球上。','A note was attached to the door.','门上贴着一张便条。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l18','in response to','',NULL,'/ɪn rɪˈspɑːns tə/','The forms move in response to the wind.','这些造型随风摆动。','He acted in response to their request.','他应他们的要求行动。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp1','choice','{"stem":"\"Even people who take no interest ___ art notice these shapes.\"(interest 后接哪个介词)","options":["on","for","in","of"],"answer_index":2,"stem_cn":"连对艺术不感兴趣的人也会注意到这些形状。","explanation_cn":"take (an) interest in sth“对…感兴趣”,介词固定用 in。✓ take no interest in art. ✗ on / for / of:interest 搭配的介词是 in。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp1','choice','{"stem":"\"There were long thin wires attached ___ metal spheres.\"(attach 后接哪个介词)","options":["to","on","of","in"],"answer_index":0,"stem_cn":"有细长的金属丝连着金属球。","explanation_cn":"be attached to sth“连在…上”,介词固定用 to。✓ wires attached to metal spheres. ✗ in / on / of:attach 搭配的介词是 to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp1','choice','{"stem":"\"A notice was attached ___ the wall near the door.\"(attach 后接哪个介词)","options":["at","to","with","from"],"answer_index":1,"stem_cn":"门边墙上贴着一张告示。","explanation_cn":"attach to“贴/连在…上”,介词用 to。✓ a notice attached to the wall. ✗ with / at / from:attach 搭配的介词是 to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp2','choice','{"stem":"\"Strange forms are ___ display in parks and outside stores.\"(“在展出”用哪个介词)","options":["to","at","on","in"],"answer_index":2,"stem_cn":"奇怪的造型在公园里、商店外展出。","explanation_cn":"“在展出、陈列中”用 on display。✓ on display in parks. ✗ in / at / to:固定搭配是 on display。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp2','choice','{"stem":"\"Oddly shaped forms are suspended ___ the ceiling.\"(suspend 后接哪个介词)","options":["at","from","on","in"],"answer_index":1,"stem_cn":"造型古怪的东西从天花板上垂下来。","explanation_cn":"be suspended from“从…垂下/悬挂”,介词用 from。✓ suspended from the ceiling. ✗ on / in / at:suspend 搭配的介词是 from。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp2','choice','{"stem":"\"The shapes move in response ___ a gust of wind.\"(in response 后接哪个介词)","options":["for","with","of","to"],"answer_index":3,"stem_cn":"这些造型随一阵风摆动。","explanation_cn":"in response to“响应…、随…而动”,介词用 to。✓ move in response to a gust of wind. ✗ of / for / with:固定搭配是 in response to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp3','choice','{"stem":"\"Such swinging shapes are familiar ___ everybody.\"(familiar 后接哪个介词)","options":["to","for","of","with"],"answer_index":0,"stem_cn":"这种摆动的造型人人都熟悉。","explanation_cn":"be familiar to sb“为某人所熟悉”,介词用 to。✓ familiar to everybody. ✗ with(be familiar with sth 熟悉某事)/ for / of:这里“为人所熟悉”用 to。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp3','choice','{"stem":"\"We have gotten used ___ seeing modern art in public.\"(be/get used 后接哪个介词)","options":["of","to","with","for"],"answer_index":1,"stem_cn":"我们已经习惯在公共场所看到现代艺术。","explanation_cn":"be/get used to (doing)“习惯于”,介词用 to。✓ gotten used to seeing modern art. ✗ with / of / for:固定搭配是 used to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp3','choice','{"stem":"\"Sparks were emitted ___ small black boxes.\"(emit 后接哪个介词)","options":["of","to","from","in"],"answer_index":2,"stem_cn":"火花从小黑盒子里迸出。","explanation_cn":"emit … from“从…发出/放射”,介词用 from。✓ sparks were emitted from the boxes. ✗ to / in / of:emit 搭配的介词是 from。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp4','choice','{"stem":"\"one baby, two ___.\"(辅音字母+y 变复数)","options":["babis","babies","babys","babyes"],"answer_index":1,"stem_cn":"一个婴儿,两个婴儿。","explanation_cn":"baby 以“辅音字母 + y”结尾,变复数去 y 加 -ies。✓ two babies. ✗ babys / babyes / babis:拼写错误。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp4','choice','{"stem":"\"one city, many ___.\"(辅音字母+y 变复数)","options":["cies","cityes","citys","cities"],"answer_index":3,"stem_cn":"一个城市,许多城市。","explanation_cn":"city 以“辅音字母 + y”结尾,变复数去 y 加 -ies。✓ many cities. ✗ citys / cityes / cies:拼写错误。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp4','choice','{"stem":"\"He never ___ very hard.\"(try 的第三人称单数)","options":["try","tries","trys","trees"],"answer_index":1,"stem_cn":"他从不很努力地尝试。","explanation_cn":"try 以“辅音字母 + y”结尾,第三人称单数去 y 加 -ies。✓ he never tries hard. ✗ trys / try / trees:拼写错误。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp5','choice','{"stem":"\"one donkey, two ___.\"(元音字母+y 直接加 -s)","options":["donkeyes","donkis","donkies","donkeys"],"answer_index":3,"stem_cn":"一头驴,两头驴。","explanation_cn":"donkey 以“元音字母 + y”结尾,变复数直接加 -s。✓ two donkeys. ✗ donkies / donkeyes / donkis:元音+y 不变 ies。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp5','choice','{"stem":"\"one day, seven ___.\"(元音字母+y 直接加 -s)","options":["daies","days","dayes","dais"],"answer_index":1,"stem_cn":"一天,七天。","explanation_cn":"day 以“元音字母 + y”结尾,变复数直接加 -s。✓ seven days. ✗ dais / dayes / daies:元音+y 直接加 -s。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp5','choice','{"stem":"\"She always ___ the bills on time.\"(pay 的第三人称单数)","options":["paics","payes","pays","paies"],"answer_index":2,"stem_cn":"她总是按时付账单。","explanation_cn":"pay 以“元音字母 + y”结尾,第三人称单数直接加 -s。✓ she always pays the bills. ✗ paies / payes / paics:元音+y 直接加 -s。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp6','choice','{"stem":"\"A shape made of stone, metal, or clay for people to look at is a ___.\"(“雕塑”用哪个词)","options":["song","poem","painting","sculpture"],"answer_index":3,"stem_cn":"用石、金属或黏土做成供人观赏的造型。","explanation_cn":"用石、金属或黏土做成供人观赏的造型是 sculpture(雕塑)。✓ modern sculpture. ✗ painting 绘画;✗ poem 诗;✗ song 歌——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp6','choice','{"stem":"\"When two magnets push each other away, they ___ each other.\"(“排斥”用哪个词)","options":["attract","repel","break","melt"],"answer_index":1,"stem_cn":"两块磁铁互相推开就是排斥。","explanation_cn":"两块磁铁互相推开用 repel(排斥)。✓ attracted or repelled each other. ✗ attract 吸引(相反);✗ melt 融化;✗ break 打破——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',5,'am3_l18_gp6','choice','{"stem":"\"Strange and unusual in a way that is hard to explain is ___.\"(“奇异的”用哪个词)","options":["peculiar","ordinary","cheap","gentle"],"answer_index":0,"stem_cn":"奇怪得难以解释的。","explanation_cn":"奇怪得难以解释的是 peculiar(奇异的)。✓ these peculiar forms. ✗ ordinary 普通;✗ gentle 温和;✗ cheap 便宜——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"sculpture 的意思是:","options":["绘画","照片","雕塑","地图"],"answer_index":2,"explanation_cn":"sculpture = 雕塑。✓ modern sculpture 现代雕塑。\n顺带记:绘画 = painting;照片 = photo;地图 = map."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"mistaken 的意思是:","options":["昂贵的","错误的","巨大的","正确的"],"answer_index":1,"explanation_cn":"mistaken = 错误的。✓ the idea is mistaken 这种想法是错的。\n顺带记:正确的 = correct;昂贵的 = expensive;巨大的 = huge."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"exhibit 的意思是:","options":["门票","顾客","画家","展品,陈列品"],"answer_index":3,"explanation_cn":"exhibit = 展品、陈列品。✓ do not touch the exhibits 请勿触摸展品。\n顺带记:顾客 = customer;画家 = painter;门票 = ticket."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"sphere 的意思是:","options":["直线","球体","三角形","立方体"],"answer_index":1,"explanation_cn":"sphere = 球体。✓ metal spheres 金属球。\n顺带记:立方体 = cube;三角形 = triangle;直线 = line."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"repel 的意思是:","options":["吸引","融化","排斥","连接"],"answer_index":2,"explanation_cn":"repel = 排斥。✓ attracted or repelled each other 互相吸引又排斥。\n顺带记:吸引 = attract;融化 = melt;连接 = connect."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',6,NULL,'choice','{"stem":"peculiar 的意思是:","options":["奇异的","安静的","普通的","明亮的"],"answer_index":0,"explanation_cn":"peculiar = 奇异的。✓ these peculiar forms 这些奇异的造型。\n顺带记:普通的 = ordinary;安静的 = quiet;明亮的 = bright."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',7,NULL,'cloze','{"stem":"第 1 空","context":"Even people who take no interest ___1___ art notice modern sculpture on display in public. At a recent show, I saw a notice attached ___2___ the wall: ''Do not touch!'' Oddly shaped forms were suspended ___3___ the ceiling, and metal spheres moved ___4___ response to hidden magnets.","blank_no":1,"options":["in","on","for","of"],"answer_index":0,"explanation_cn":"take interest in sth,介词用 in。✓ take no interest in art."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',7,NULL,'cloze','{"stem":"第 2 空","context":"Even people who take no interest ___1___ art notice modern sculpture on display in public. At a recent show, I saw a notice attached ___2___ the wall: ''Do not touch!'' Oddly shaped forms were suspended ___3___ the ceiling, and metal spheres moved ___4___ response to hidden magnets.","blank_no":2,"options":["to","in","on","of"],"answer_index":0,"explanation_cn":"attach to,介词用 to。✓ a notice attached to the wall."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',7,NULL,'cloze','{"stem":"第 3 空","context":"Even people who take no interest ___1___ art notice modern sculpture on display in public. At a recent show, I saw a notice attached ___2___ the wall: ''Do not touch!'' Oddly shaped forms were suspended ___3___ the ceiling, and metal spheres moved ___4___ response to hidden magnets.","blank_no":3,"options":["from","on","in","at"],"answer_index":0,"explanation_cn":"suspend from,介词用 from。✓ forms suspended from the ceiling."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',7,NULL,'cloze','{"stem":"第 4 空","context":"Even people who take no interest ___1___ art notice modern sculpture on display in public. At a recent show, I saw a notice attached ___2___ the wall: ''Do not touch!'' Oddly shaped forms were suspended ___3___ the ceiling, and metal spheres moved ___4___ response to hidden magnets.","blank_no":4,"options":["in","on","at","of"],"answer_index":0,"explanation_cn":"in response to,固定短语,前面用 in。✓ moved in response to hidden magnets."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',8,NULL,'choice','{"stem":"What did the notice at the gallery warn visitors?","options":["Not to touch the exhibits","To take no photos","To stay very quiet","To pay an extra fee"],"answer_index":0,"explanation_cn":"课文说 a notice…: ''Do not touch the exhibits. Some of them are dangerous!''——告示叫人别碰展品。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',8,NULL,'choice','{"stem":"What had been done to the metal spheres?","options":["They had been hidden","They had been broken","They had been painted","They had been magnetized"],"answer_index":3,"explanation_cn":"课文说 The spheres had been magnetized——金属球被磁化了,所以会吸引和排斥。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',8,NULL,'choice','{"stem":"What came out of the small black boxes?","options":["Smoke rings","Music","Sparks","Water"],"answer_index":2,"explanation_cn":"课文说 Sparks were emitted from little black boxes——小黑盒子里迸出火花。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',9,NULL,'choice','{"stem":"你想说\"他对现代艺术不感兴趣\"(interest in):","options":["He takes no interest on modern art.","He takes no interest for modern art.","He takes no interest in modern art.","He takes no interest of modern art."],"answer_index":2,"explanation_cn":"take interest in sth,介词用 in。✓ He takes no interest in modern art. 场合:说某人对某事(不)感兴趣。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',9,NULL,'choice','{"stem":"你想说\"墙上贴着一张告示\"(attached to):","options":["A notice was attached in the wall.","A notice was attached on the wall.","A notice was attached of the wall.","A notice was attached to the wall."],"answer_index":3,"explanation_cn":"be attached to sth,介词用 to。✓ A notice was attached to the wall. 场合:说某物贴/连在别的东西上。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',9,NULL,'choice','{"stem":"你想说\"这些造型随风摆动\"(in response to):","options":["The forms move in response of the wind.","The forms move in response to the wind.","The forms move in response for the wind.","The forms move on response to the wind."],"answer_index":1,"explanation_cn":"in response to,固定短语。✓ The forms move in response to the wind. 场合:说某物随某种刺激而反应。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"sculpture 的意思是:","options":["照片","绘画","雕塑","地图"],"answer_index":2,"explanation_cn":"sculpture = 雕塑。✓ modern sculpture."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"peculiar 的意思是:","options":["明亮的","安静的","普通的","奇异的"],"answer_index":3,"explanation_cn":"peculiar = 奇异的。✓ these peculiar forms."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"\"People who take no interest ___ art still notice them.\"(interest 后接介词)","options":["in","on","of","for"],"answer_index":0,"stem_cn":"对艺术不感兴趣的人也会注意到它们。","explanation_cn":"take interest in sth,介词用 in。✓ take no interest in art. ✗ on / for / of:interest 搭配 in。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"\"one city, many ___.\"(辅音字母+y 变复数)","options":["cityes","cities","citys","cies"],"answer_index":1,"stem_cn":"一个城市,许多城市。","explanation_cn":"city 以“辅音字母 + y”结尾,变复数去 y 加 -ies。✓ many cities. ✗ citys / cityes / cies:拼写错误。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"\"on display\" 的意思是:","options":["在维修","被收藏起来","在展出,在陈列","已售完"],"answer_index":2,"explanation_cn":"on display = 在展出、在陈列。✓ on display in the park 在公园里展出。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"\"attached to\" 的意思是:","options":["远离…","连接在…上","隐藏于…后","从…上取下"],"answer_index":1,"explanation_cn":"attached to = 连接/系在…上。✓ attached to the wall 贴在墙上。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"Where can modern sculpture be seen, according to the writer?","options":["Only in private homes","Only inside museums","In public places, not only museums","Nowhere anymore"],"answer_index":2,"passage":"These days modern sculpture hardly surprises anyone. The idea that modern art can only be seen in museums is mistaken. Even people who take no interest in art cannot help noticing strange shapes on display in the parks and squares of many cities. We have all gotten used to them; some so-called ''modern'' pieces have stood in public for nearly eighty years. Even so, I was surprised by a recent exhibition downtown. The first thing I saw when I walked into the gallery was a notice attached to the wall: ''Do not touch the exhibits. Some of them are dangerous!'' The objects on display were pieces of moving sculpture. Oddly shaped forms suspended from the ceiling, which sway in response to a gust of wind, are familiar to everybody. These exhibits, however, were different. Lined up along one wall were long thin wires attached to metal spheres. The spheres had been magnetized, so they attracted or repelled one another all day long. In the center of the hall stood tall structures full of colored lights that flickered like traffic signals gone mad. Sparks were emitted from little black boxes, and red lamps flashed on and off angrily. The whole room felt like a display of prehistoric electronic gadgets. These peculiar forms seemed designed not only to shock people emotionally, but to give them a real electric shock as well!","explanation_cn":"课文说 modern sculpture on display in the parks and squares——现代雕塑不只在博物馆,也在公共场所。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"Why were these exhibits called dangerous?","options":["They might fall over","They could give an electric shock","They had sharp edges","They were extremely heavy"],"answer_index":1,"passage":"These days modern sculpture hardly surprises anyone. The idea that modern art can only be seen in museums is mistaken. Even people who take no interest in art cannot help noticing strange shapes on display in the parks and squares of many cities. We have all gotten used to them; some so-called ''modern'' pieces have stood in public for nearly eighty years. Even so, I was surprised by a recent exhibition downtown. The first thing I saw when I walked into the gallery was a notice attached to the wall: ''Do not touch the exhibits. Some of them are dangerous!'' The objects on display were pieces of moving sculpture. Oddly shaped forms suspended from the ceiling, which sway in response to a gust of wind, are familiar to everybody. These exhibits, however, were different. Lined up along one wall were long thin wires attached to metal spheres. The spheres had been magnetized, so they attracted or repelled one another all day long. In the center of the hall stood tall structures full of colored lights that flickered like traffic signals gone mad. Sparks were emitted from little black boxes, and red lamps flashed on and off angrily. The whole room felt like a display of prehistoric electronic gadgets. These peculiar forms seemed designed not only to shock people emotionally, but to give them a real electric shock as well!","explanation_cn":"课文说 to give them a real electric shock as well——这些展品可能真的电人一下,所以危险。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"What did the colored lights look like?","options":["A steady rainbow","A single candle","Traffic signals gone mad","A calm sunset"],"answer_index":2,"audio":"These days modern sculpture hardly surprises anyone. The idea that modern art can only be seen in museums is mistaken. Even people who take no interest in art cannot help noticing strange shapes on display in the parks and squares of many cities. We have all gotten used to them; some so-called ''modern'' pieces have stood in public for nearly eighty years. Even so, I was surprised by a recent exhibition downtown. The first thing I saw when I walked into the gallery was a notice attached to the wall: ''Do not touch the exhibits. Some of them are dangerous!'' The objects on display were pieces of moving sculpture. Oddly shaped forms suspended from the ceiling, which sway in response to a gust of wind, are familiar to everybody. These exhibits, however, were different. Lined up along one wall were long thin wires attached to metal spheres. The spheres had been magnetized, so they attracted or repelled one another all day long. In the center of the hall stood tall structures full of colored lights that flickered like traffic signals gone mad. Sparks were emitted from little black boxes, and red lamps flashed on and off angrily. The whole room felt like a display of prehistoric electronic gadgets. These peculiar forms seemed designed not only to shock people emotionally, but to give them a real electric shock as well!","explanation_cn":"课文说 lights that flickered like traffic signals gone mad——彩灯像发疯的交通信号灯一样闪。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l18',10,NULL,'choice','{"stem":"How did the writer feel about the exhibition?","options":["Bored","Surprised","Frightened away at the door","Completely uninterested"],"answer_index":1,"audio":"These days modern sculpture hardly surprises anyone. The idea that modern art can only be seen in museums is mistaken. Even people who take no interest in art cannot help noticing strange shapes on display in the parks and squares of many cities. We have all gotten used to them; some so-called ''modern'' pieces have stood in public for nearly eighty years. Even so, I was surprised by a recent exhibition downtown. The first thing I saw when I walked into the gallery was a notice attached to the wall: ''Do not touch the exhibits. Some of them are dangerous!'' The objects on display were pieces of moving sculpture. Oddly shaped forms suspended from the ceiling, which sway in response to a gust of wind, are familiar to everybody. These exhibits, however, were different. Lined up along one wall were long thin wires attached to metal spheres. The spheres had been magnetized, so they attracted or repelled one another all day long. In the center of the hall stood tall structures full of colored lights that flickered like traffic signals gone mad. Sparks were emitted from little black boxes, and red lamps flashed on and off angrily. The whole room felt like a display of prehistoric electronic gadgets. These peculiar forms seemed designed not only to shock people emotionally, but to give them a real electric shock as well!","explanation_cn":"课文说 I was surprised by a recent exhibition——作者对这场展览感到吃惊。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l19',3,4,19,'A Very Dear Cat','一只贵重的宝贝猫','动词形式综合复习(一般过去 / 过去完成 had done / 被动系表 were astounded 等混合运用),外加逗号的五种常见用法:句首状语后加逗号、同位语用逗号隔开、列举时用逗号、插入语 however 用逗号隔开、非限定性从句用逗号标出(原创承载 NCE3 L19 考点·净化:把''绑架勒索赎金''改写为''猫溜进豪华宠物度假村,主人付巨额账单赎回'',保留''dear=心爱+昂贵''的双关与''在可靠的人那里''的桥段,去掉绑架勒索)','埃莉诺·拉姆齐太太是位很有钱的老太太,多年来一直和她的猫拉斯特斯合住一套公寓。拉斯特斯过着极有规律的日子:每天傍晚出去溜达一小会儿,七点前准回家。可有天傍晚,他没能回来。深爱这只猫的拉姆齐太太急坏了,到处找也找不着。拉斯特斯失踪三天后,邮箱里来了一张精致的卡片,寄自全县最豪华的宠物度假村“胡须庄园”。卡上说:拉斯特斯大概是厌倦了平淡的日子,从花园门溜了进来,住下就当自己是主人;他“在可靠的人那里”,得到悉心照料,拉姆齐太太若想接他回去,只需付清账单。她差点晕过去——那张印在厚厚硬纸板上的账单,足足一千美元。原来这三天里,拉斯特斯天天被梳毛、喂三文鱼,像王室一样被伺候着。拉姆齐太太从银行取出钱,径直开车过去。第二天傍晚,拉斯特斯准时七点晃回了家,吃得圆滚滚、毛发油亮,一副心满意足的样子。她把经过一说,朋友们全惊呆了。她只是笑笑,说拉斯特斯一向是她的心肝宝贝——而想想她付的那笔钱,如今这猫可真是“贵重”得不止一层意思了!','{"q":"Listen and answer — Why was Rastus ''very dear'' in more ways than one?","options":["He was both deeply loved and very expensive","He was the oldest cat in town","He was a rare and famous breed","He could do clever tricks"],"answer_index":0}'::jsonb,'{"title":"动词形式复习 + 逗号的用法","intro":"①本课把学过的动词时态放在一起复习:一般过去(took / failed)、过去完成 had done(had shared / had wandered)、被动或系表(were astounded)。读时留意每个动词为什么用这种形式。②逗号(comma)常见五种用法:(a)句首状语后加逗号:Three days later, a card arrived. (b)同位语两边加逗号:Mrs. Ramsay, a wealthy old lady, loved her cat. (c)列举各项之间加逗号:milk, bread, and eggs. (d)插入语 however 两边加逗号:The bill, however, was huge. (e)非限定性从句用逗号标出:The cat, which loved salmon, grew plump.","table":{"headers":["逗号用法","说明","例子"],"rows":[["句首状语后","先说时间/条件,再加逗号","Three days later, a card arrived."],["同位语两边","补充说明用逗号隔开","Mrs. Ramsay, a wealthy old lady, …"],["列举各项","并列的东西之间加逗号","milk, bread, and eggs"],["however / which 从句","插入语、非限定性从句用逗号","The bill, however, was huge."]]},"specialRules":[{"rule":"同位语和插入语(如 however)要用一对逗号把它整段隔开:漏掉任何一个逗号都算错。","mark":"同位语 / however"},{"rule":"非限定性从句(补充信息、可去掉)前后要加逗号;限定性从句(不可去掉)则不加。","mark":"which 从句"},{"rule":"美语拼写与用词:apartment(英式 flat)、the mail(英式 post)、vacation(英式 holiday)。本课已按美语写。","mark":"apartment / mail"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l19',1,NULL,'Mrs. Eleanor Ramsay, a very wealthy old lady, had shared her apartment with her cat, Rastus, for a great many years. Rastus led an orderly life. He usually took a short walk in the evenings, and he was always home by seven o''clock.','埃莉诺·拉姆齐太太是位很有钱的老太太,多年来一直和她的猫拉斯特斯合住一套公寓。拉斯特斯过着极有规律的日子:每天傍晚出去溜达一小会儿,七点前准回家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l19',2,NULL,'One evening, however, he failed to arrive. Mrs. Ramsay, who loved him dearly, grew very worried. She looked everywhere, but she could not find him. Three days after Rastus''s disappearance, a fancy card arrived in the mail. It came from Whisker Manor, the most luxurious pet resort in the county.','可有天傍晚,他没能回来。深爱这只猫的拉姆齐太太急坏了,到处找也找不着。拉斯特斯失踪三天后,邮箱里来了一张精致的卡片,寄自全县最豪华的宠物度假村“胡须庄园”。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l19',3,NULL,'The note explained that Rastus, tired of his quiet routine, had wandered in through their garden gate and settled down as if he owned the place. He was, the manager wrote, in very safe hands. If Mrs. Ramsay wished to collect him, she had only to pay his bill.','卡上说:拉斯特斯大概是厌倦了平淡的日子,从花园门溜了进来,住下就当自己是主人;他“在可靠的人那里”,得到悉心照料。拉姆齐太太若想接他回去,只需付清账单。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l19',4,NULL,'At first, she nearly fainted, for the bill, printed neatly on thick cardboard, came to a thousand dollars. The staff, it seemed, had taken considerable pride in brushing him, feeding him salmon, and pampering him like royalty.','她差点晕过去——那张印在厚厚硬纸板上的账单,足足一千美元。原来这三天里,度假村的员工把伺候他当成了极大的乐事:给他梳毛、喂三文鱼,像王室一样宠着他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l19',5,NULL,'Mrs. Ramsay withdrew the money from her bank and drove straight over. The next evening, punctually at seven o''clock, Rastus strolled home, looking plump, glossy, and thoroughly pleased with himself. Her friends were astounded when she told them the story. She only smiled and said that Rastus had always been dear to her. Considering the amount she had paid, he was now dear in more ways than one!','拉姆齐太太从银行取出钱,径直开车过去。第二天傍晚,拉斯特斯准时七点晃回了家,吃得圆滚滚、毛发油亮,一副心满意足的样子。她把经过一说,朋友们全惊呆了。她只是笑笑,说拉斯特斯一向是她的心肝宝贝——而想想她付的那笔钱,如今这猫可真是“贵重”得不止一层意思了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
