INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l19','be in safe hands','',NULL,'/bi ɪn seɪf hændz/','Rastus was in safe hands at the resort.','拉斯特斯在度假村受到妥善照料。','Don''t worry, the kids are in safe hands.','别担心,孩子们有人好好照看。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l19','change one''s mind','',NULL,'/tʃeɪndʒ wʌnz maɪnd/','She almost changed her mind about paying.','她差点改变主意不付钱了。','He changed his mind at the last minute.','他在最后一刻改了主意。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l19','in more ways than one','',NULL,'/ɪn mɔːr weɪz ðæn wʌn/','The cat was dear in more ways than one.','这只猫“贵重”得不止一层意思。','This trip helped me in more ways than one.','这趟旅行在不止一个方面帮到了我。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l19','pay a bill','',NULL,'/peɪ ə bɪl/','She had to pay a huge bill to get him back.','她得付一大笔账单才能把它接回来。','Remember to pay the electricity bill.','记得付电费账单。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp1','choice','{"stem":"\"Every evening Rastus ___ a short walk and came home by seven.\"(一般过去)","options":["took","takes","has taken","taking"],"answer_index":0,"stem_cn":"每天傍晚拉斯特斯都去散会儿步,七点前回家。","explanation_cn":"讲过去反复发生的习惯,用一般过去 took。✓ Every evening Rastus took a short walk. ✗ takes 现在;✗ has taken 完成;✗ taking 缺谓语形式。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp1','choice','{"stem":"\"One evening, however, he ___ to arrive on time.\"(一般过去)","options":["failing","has failed","failed","fails"],"answer_index":2,"stem_cn":"可有天傍晚,他没能按时回来。","explanation_cn":"讲过去某晚发生的事,用一般过去 failed。✓ he failed to arrive on time. ✗ fails 现在;✗ has failed 完成;✗ failing 缺谓语形式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp1','choice','{"stem":"\"Her friends ___ when she told them the whole story.\"(一般过去:“感到震惊”)","options":["astound","are astounded","astounding","were astounded"],"answer_index":3,"stem_cn":"她把整件事一说,朋友们都惊呆了。","explanation_cn":"“感到震惊”用 be astounded,过去用 were astounded。✓ Her friends were astounded. ✗ are astounded 现在;✗ astound 主动原形;✗ astounding 是“令人震惊的”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp2','choice','{"stem":"\"Mrs. Ramsay ___ her apartment with the cat for many years.\"(过去完成:此前一直)","options":["is sharing","shares","had shared","share"],"answer_index":2,"stem_cn":"拉姆齐太太多年来一直和这只猫合住。","explanation_cn":"“在过去某点之前一直……”用过去完成 had done。✓ had shared her apartment for many years. ✗ shares / is sharing / share:时态不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp2','choice','{"stem":"\"The note said Rastus ___ in through the garden gate.\"(过去完成:“早先已溜进”)","options":["wanders","is wandering","wander","had wandered"],"answer_index":3,"stem_cn":"便条说拉斯特斯早先从花园门溜了进去。","explanation_cn":"“比说话时更早已经溜进去”用过去完成 had done。✓ Rastus had wandered in. ✗ wanders / is wandering / wander:时态不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp2','choice','{"stem":"\"Considering the amount she ___, the cat was dear indeed.\"(过去完成:“已付”)","options":["had paid","pay","is paying","pays"],"answer_index":0,"stem_cn":"想想她付的那笔钱,这猫可真够“贵”的。","explanation_cn":"“想想她(早已)付的钱”,更早的动作用过去完成 had paid。✓ the amount she had paid. ✗ pays / is paying / pay:时态不对。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp3','choice','{"stem":"下面哪一句在列举东西时,逗号用得正确?","options":["He, was brushed fed and pampered.","He was, brushed fed and pampered.","He was brushed fed and, pampered.","He was brushed, fed, and pampered."],"answer_index":3,"stem_cn":"列举并列的东西时,各项之间要用逗号分隔。","explanation_cn":"列举并列的动作时,各项之间用逗号分隔。✓ brushed, fed, and pampered. 其余三句逗号位置错乱。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp3','choice','{"stem":"下面哪一句在句首的时间状语后,正确地加了逗号?","options":["Three days later, a card arrived.","Three, days later a card arrived.","Three days, later a card arrived.","Three days later a, card arrived."],"answer_index":0,"stem_cn":"先说时间状语,再用逗号与主句隔开。","explanation_cn":"句首的时间状语后面要用逗号,与主句隔开。✓ Three days later, a card arrived. 其余三句逗号乱放。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp3','choice','{"stem":"下面哪一句列举时标点用得正确?","options":["I bought milk bread, and, eggs.","I bought, milk bread and eggs.","I, bought milk bread and eggs.","I bought milk, bread, and eggs."],"answer_index":3,"stem_cn":"并列的名词之间用逗号分隔。","explanation_cn":"列举名词时,各项之间用逗号。✓ milk, bread, and eggs. 其余三句逗号位置错误。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp4','choice','{"stem":"下面哪一句用逗号正确地隔开了同位语(补充说明)?","options":["Mrs. Ramsay a wealthy old lady, loved her cat.","Mrs. Ramsay, a wealthy old lady, loved her cat.","Mrs. Ramsay, a wealthy old lady loved her cat.","Mrs. Ramsay a wealthy old lady loved her cat."],"answer_index":1,"stem_cn":"同位语要用一对逗号前后隔开。","explanation_cn":"同位语“a wealthy old lady”要用一对逗号前后隔开。✓ 正确用了两个逗号。其余三句缺一个或位置不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp4','choice','{"stem":"下面哪一句用同位语正确地介绍了这家度假村?","options":["Whisker Manor, the finest pet resort, took him in.","Whisker Manor the finest pet resort, took him in.","Whisker, Manor the finest pet resort took him in.","Whisker Manor, the finest pet resort took him in."],"answer_index":0,"stem_cn":"同位语两边都要有逗号。","explanation_cn":"同位语两边都要有逗号。✓ Whisker Manor, the finest pet resort, took him in. 其余三句漏逗号或放错。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp4','choice','{"stem":"下面哪一句同位语的标点用得正确?","options":["Rastus her only companion, came home at last.","Rastus, her only companion came home at last.","Rastus her only, companion came home at last.","Rastus, her only companion, came home at last."],"answer_index":3,"stem_cn":"补充说明“她唯一的伙伴”要用一对逗号隔开。","explanation_cn":"同位语“her only companion”要用一对逗号隔开。✓ 正确。其余三句缺一个逗号或位置乱。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp5','choice','{"stem":"下面哪一句用逗号正确地隔开了插入语 however?","options":["There were however, no cats at home.","There were, however, no cats at home.","There, were however no cats at home.","There were however no, cats at home."],"answer_index":1,"stem_cn":"插入语 however 要用一对逗号前后隔开。","explanation_cn":"插入语 however 要用一对逗号前后隔开。✓ There were, however, no cats at home. 其余三句逗号位置不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp5','choice','{"stem":"下面哪一句正确地用逗号标出了非限定性(可去掉的补充)从句?","options":["The cat which, loved salmon grew plump.","The cat, which loved salmon grew plump.","The cat which loved salmon, grew plump.","The cat, which loved salmon, grew plump."],"answer_index":3,"stem_cn":"补充信息、可去掉的从句前后要加逗号。","explanation_cn":"补充信息、可去掉的从句(which loved salmon)前后要加逗号。✓ 正确。其余三句缺一个逗号或放错。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp5','choice','{"stem":"下面哪一句 however 的标点用得正确?","options":["The bill, however, was enormous.","The, bill however was enormous.","The bill however was, enormous.","The bill however, was enormous."],"answer_index":0,"stem_cn":"插入语 however 两边都要有逗号。","explanation_cn":"插入语 however 两边都要有逗号。✓ The bill, however, was enormous. 其余三句逗号缺失或错位。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp6','choice','{"stem":"\"A person who has a lot of money is ___.\"(“富有的”用哪个词)","options":["angry","hungry","wealthy","sleepy"],"answer_index":2,"stem_cn":"很有钱的人是富有的。","explanation_cn":"很有钱的人是 wealthy(富有的)。✓ a wealthy old lady. ✗ hungry 饿;✗ sleepy 困;✗ angry 生气——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp6','choice','{"stem":"\"To take money out of your bank account is to ___ it.\"(“取(钱)”用哪个词)","options":["count","withdraw","borrow","lose"],"answer_index":1,"stem_cn":"从银行账户里取钱。","explanation_cn":"从银行账户取钱用 withdraw。✓ withdrew the money from her bank. ✗ borrow 借入;✗ count 数;✗ lose 丢——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',5,'am3_l19_gp6','choice','{"stem":"\"Arriving exactly on time is arriving ___.\"(“准时地”用哪个词)","options":["slowly","rarely","quietly","punctually"],"answer_index":3,"stem_cn":"恰好按时到达。","explanation_cn":"恰好按时到达是 punctually(准时地)。✓ punctually at seven. ✗ slowly 慢;✗ quietly 安静;✗ rarely 很少——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"wealthy 的意思是:","options":["年轻的","健康的","富有的","贫穷的"],"answer_index":2,"explanation_cn":"wealthy = 富有的、有钱的。✓ a very wealthy old lady 很有钱的老太太。\n顺带记:贫穷的 = poor;年轻的 = young;健康的 = healthy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"orderly 的意思是:","options":["吵闹的","危险的","混乱的","有规律的,井井有条的"],"answer_index":3,"explanation_cn":"orderly = 有规律的、井井有条的。✓ an orderly life 极有规律的生活。\n顺带记:混乱的 = messy;危险的 = dangerous;吵闹的 = noisy."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"disappearance 的意思是:","options":["到达","失踪,消失","出生","庆祝"],"answer_index":1,"explanation_cn":"disappearance = 失踪、消失。✓ after Rastus''s disappearance 拉斯特斯失踪之后。\n顺带记:到达 = arrival;出生 = birth;庆祝 = celebration."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"withdraw 的意思是:","options":["(从银行)取钱","存入","花光","借出"],"answer_index":0,"explanation_cn":"withdraw = (从银行)取钱。✓ withdrew the money 取出那笔钱。\n顺带记:存入 = deposit;借出 = lend;花光 = spend."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"punctually 的意思是:","options":["缓慢地","准时地","迟到地","偶然地"],"answer_index":1,"explanation_cn":"punctually = 准时地。✓ punctually at seven o''clock 准时七点。\n顺带记:迟到地 = late;缓慢地 = slowly;偶然地 = accidentally."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',6,NULL,'choice','{"stem":"astound 的意思是:","options":["使疲倦","使无聊","使吃惊","使安心"],"answer_index":2,"explanation_cn":"astound = 使吃惊、使震惊。✓ her friends were astounded 朋友们都惊呆了。\n顺带记:使无聊 = bore;使安心 = reassure;使疲倦 = tire."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',7,NULL,'cloze','{"stem":"第 1 空","context":"Mrs. Ramsay ___1___ her apartment with Rastus for years. One evening the cat ___2___ to come home. Three days later she learned that he ___3___ into a luxury pet resort. She ___4___ the money from her bank and happily paid the bill.","blank_no":1,"options":["had shared","shares","is sharing","share"],"answer_index":0,"explanation_cn":"“过去某点之前一直……”用过去完成 had shared。✓ had shared her apartment for years."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',7,NULL,'cloze','{"stem":"第 2 空","context":"Mrs. Ramsay ___1___ her apartment with Rastus for years. One evening the cat ___2___ to come home. Three days later she learned that he ___3___ into a luxury pet resort. She ___4___ the money from her bank and happily paid the bill.","blank_no":2,"options":["failed","fails","has failed","failing"],"answer_index":0,"explanation_cn":"讲过去某晚的事,用一般过去 failed。✓ the cat failed to come home."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',7,NULL,'cloze','{"stem":"第 3 空","context":"Mrs. Ramsay ___1___ her apartment with Rastus for years. One evening the cat ___2___ to come home. Three days later she learned that he ___3___ into a luxury pet resort. She ___4___ the money from her bank and happily paid the bill.","blank_no":3,"options":["had wandered","wanders","is wandering","wander"],"answer_index":0,"explanation_cn":"“更早已经溜进去”用过去完成 had wandered。✓ he had wandered into a pet resort."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',7,NULL,'cloze','{"stem":"第 4 空","context":"Mrs. Ramsay ___1___ her apartment with Rastus for years. One evening the cat ___2___ to come home. Three days later she learned that he ___3___ into a luxury pet resort. She ___4___ the money from her bank and happily paid the bill.","blank_no":4,"options":["withdrew","withdraws","is withdrawing","withdraw"],"answer_index":0,"explanation_cn":"讲过去做的动作,用一般过去 withdrew。✓ She withdrew the money from her bank."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',8,NULL,'choice','{"stem":"Why did Mrs. Ramsay grow worried one evening?","options":["Her phone kept ringing","A stranger knocked at the door","Rastus did not come home by seven","It suddenly started to rain"],"answer_index":2,"explanation_cn":"课文说 he failed to arrive…she got very worried——猫没在七点前回家,她就担心了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',8,NULL,'choice','{"stem":"Where had Rastus actually been for three days?","options":["At the vet''s office","At a luxury pet resort","Lost in the woods","Locked in a shed"],"answer_index":1,"explanation_cn":"课文说 It came from Whisker Manor, the most luxurious pet resort——这三天猫其实在豪华宠物度假村。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',8,NULL,'choice','{"stem":"Why was the cat ''dear in more ways than one''?","options":["He was heavy and large","He was old and slow","He was rare and famous","He was both loved and very costly"],"answer_index":3,"explanation_cn":"课文说 dear in more ways than one——既是心爱之物,又花了大价钱,所以“贵重”不止一层意思。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',9,NULL,'choice','{"stem":"你想说\"她多年来一直和这只猫合住\"(过去完成 had shared):","options":["She had shared her home with the cat for many years.","She has shared her home with the cat many years ago.","She was shared her home with the cat for many years.","She had share her home with the cat for many years."],"answer_index":0,"explanation_cn":"“过去某点之前一直……”用过去完成 had shared。✓ She had shared her home with the cat for many years. 场合:强调在过去某时之前已持续多年。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',9,NULL,'choice','{"stem":"你想说\"拉姆齐太太,一位有钱的老太太,爱她的猫\"(同位语用逗号隔开):","options":["Mrs. Ramsay, a wealthy old lady loved her cat.","Mrs. Ramsay, a wealthy old lady, loved her cat.","Mrs. Ramsay a wealthy old lady loved her cat.","Mrs. Ramsay a wealthy old lady, loved her cat."],"answer_index":1,"explanation_cn":"补充说明“一位有钱的老太太”要用一对逗号前后隔开。✓ Mrs. Ramsay, a wealthy old lady, loved her cat. 场合:给人物加一句补充介绍。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',9,NULL,'choice','{"stem":"你想说\"然而,那张账单大得吓人\"(插入语 however 用逗号隔开):","options":["The bill however, was enormous.","The, bill however was enormous.","The bill, however, was enormous.","The bill however was enormous."],"answer_index":2,"explanation_cn":"插入语 however 要用一对逗号前后隔开。✓ The bill, however, was enormous. 场合:在句中插入“然而”表转折。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"wealthy 的意思是:","options":["贫穷的","富有的","健康的","年轻的"],"answer_index":1,"explanation_cn":"wealthy = 富有的。✓ a wealthy old lady."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"withdraw 的意思是:","options":["花光","借出","(从银行)取钱","存入"],"answer_index":2,"explanation_cn":"withdraw = (从银行)取钱。✓ withdrew the money."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"\"Mrs. Ramsay ___ her apartment with the cat for years.\"(过去完成)","options":["is sharing","had shared","share","shares"],"answer_index":1,"stem_cn":"拉姆齐太太多年来一直和这只猫合住。","explanation_cn":"“过去某点之前一直……”用过去完成 had shared。✓ Mrs. Ramsay had shared her apartment with the cat for years. ✗ shares / is sharing / share:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"\"Her friends ___ when they heard the story.\"(一般过去:“感到震惊”)","options":["astound","astounding","are astounded","were astounded"],"answer_index":3,"stem_cn":"朋友们听了这故事都惊呆了。","explanation_cn":"“感到震惊”过去用 were astounded。✓ Her friends were astounded. ✗ are astounded 现在;✗ astound 原形;✗ astounding 令人震惊的。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"\"be in safe hands\" 的意思是:","options":["手受了伤","亲手去做","在可靠的人那里(得到妥善照料)","空手而归"],"answer_index":2,"explanation_cn":"be in safe hands = 在可靠的人那里,得到妥善照料。✓ Rastus was in safe hands 拉斯特斯得到了好好照看。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"\"in more ways than one\" 的意思是:","options":["再也不去了","在不止一个方面","走另一条路","只有一种办法"],"answer_index":1,"explanation_cn":"in more ways than one = 在不止一个方面。✓ dear in more ways than one “贵重”不止一层意思。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"How long was Rastus missing?","options":["Three days","One day","About a month","A whole week"],"answer_index":0,"passage":"Mrs. Eleanor Ramsay, a very wealthy old lady, had shared her apartment with her cat, Rastus, for a great many years. Rastus led an orderly life. He usually took a short walk in the evenings, and he was always home by seven o''clock. One evening, however, he failed to arrive. Mrs. Ramsay, who loved him dearly, grew very worried. She looked everywhere, but she could not find him. Three days after Rastus''s disappearance, a fancy card arrived in the mail. It came from Whisker Manor, the most luxurious pet resort in the county. The note explained that Rastus, tired of his quiet routine, had wandered in through their garden gate and settled down as if he owned the place. He was, the manager wrote, in very safe hands. If Mrs. Ramsay wished to collect him, she had only to pay his bill. At first, she nearly fainted, for the bill, printed neatly on thick cardboard, came to a thousand dollars. The staff, it seemed, had taken considerable pride in brushing him, feeding him salmon, and pampering him like royalty. Mrs. Ramsay withdrew the money from her bank and drove straight over. The next evening, punctually at seven o''clock, Rastus strolled home, looking plump, glossy, and thoroughly pleased with himself. Her friends were astounded when she told them the story. She only smiled and said that Rastus had always been dear to her. Considering the amount she had paid, he was now dear in more ways than one!","explanation_cn":"课文说 Three days after Rastus''s disappearance——猫失踪了三天。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"How did Mrs. Ramsay feel about Rastus?","options":["She had forgotten him","She was afraid of him","He was very dear to her","She wanted to give him away"],"answer_index":2,"passage":"Mrs. Eleanor Ramsay, a very wealthy old lady, had shared her apartment with her cat, Rastus, for a great many years. Rastus led an orderly life. He usually took a short walk in the evenings, and he was always home by seven o''clock. One evening, however, he failed to arrive. Mrs. Ramsay, who loved him dearly, grew very worried. She looked everywhere, but she could not find him. Three days after Rastus''s disappearance, a fancy card arrived in the mail. It came from Whisker Manor, the most luxurious pet resort in the county. The note explained that Rastus, tired of his quiet routine, had wandered in through their garden gate and settled down as if he owned the place. He was, the manager wrote, in very safe hands. If Mrs. Ramsay wished to collect him, she had only to pay his bill. At first, she nearly fainted, for the bill, printed neatly on thick cardboard, came to a thousand dollars. The staff, it seemed, had taken considerable pride in brushing him, feeding him salmon, and pampering him like royalty. Mrs. Ramsay withdrew the money from her bank and drove straight over. The next evening, punctually at seven o''clock, Rastus strolled home, looking plump, glossy, and thoroughly pleased with himself. Her friends were astounded when she told them the story. She only smiled and said that Rastus had always been dear to her. Considering the amount she had paid, he was now dear in more ways than one!","explanation_cn":"课文说 Rastus had always been dear to her——拉斯特斯一直是她的心肝宝贝。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"What did the note from the resort say about Rastus?","options":["He had run away again","He was never there","He was very sick","He was in safe hands"],"answer_index":3,"audio":"Mrs. Eleanor Ramsay, a very wealthy old lady, had shared her apartment with her cat, Rastus, for a great many years. Rastus led an orderly life. He usually took a short walk in the evenings, and he was always home by seven o''clock. One evening, however, he failed to arrive. Mrs. Ramsay, who loved him dearly, grew very worried. She looked everywhere, but she could not find him. Three days after Rastus''s disappearance, a fancy card arrived in the mail. It came from Whisker Manor, the most luxurious pet resort in the county. The note explained that Rastus, tired of his quiet routine, had wandered in through their garden gate and settled down as if he owned the place. He was, the manager wrote, in very safe hands. If Mrs. Ramsay wished to collect him, she had only to pay his bill. At first, she nearly fainted, for the bill, printed neatly on thick cardboard, came to a thousand dollars. The staff, it seemed, had taken considerable pride in brushing him, feeding him salmon, and pampering him like royalty. Mrs. Ramsay withdrew the money from her bank and drove straight over. The next evening, punctually at seven o''clock, Rastus strolled home, looking plump, glossy, and thoroughly pleased with himself. Her friends were astounded when she told them the story. She only smiled and said that Rastus had always been dear to her. Considering the amount she had paid, he was now dear in more ways than one!","explanation_cn":"课文说 He was, the manager wrote, in very safe hands——度假村说猫得到妥善照料。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l19',10,NULL,'choice','{"stem":"How did Rastus look when he came home?","options":["Hurt and limping","Plump and pleased with himself","Wet and cold","Thin and frightened"],"answer_index":1,"audio":"Mrs. Eleanor Ramsay, a very wealthy old lady, had shared her apartment with her cat, Rastus, for a great many years. Rastus led an orderly life. He usually took a short walk in the evenings, and he was always home by seven o''clock. One evening, however, he failed to arrive. Mrs. Ramsay, who loved him dearly, grew very worried. She looked everywhere, but she could not find him. Three days after Rastus''s disappearance, a fancy card arrived in the mail. It came from Whisker Manor, the most luxurious pet resort in the county. The note explained that Rastus, tired of his quiet routine, had wandered in through their garden gate and settled down as if he owned the place. He was, the manager wrote, in very safe hands. If Mrs. Ramsay wished to collect him, she had only to pay his bill. At first, she nearly fainted, for the bill, printed neatly on thick cardboard, came to a thousand dollars. The staff, it seemed, had taken considerable pride in brushing him, feeding him salmon, and pampering him like royalty. Mrs. Ramsay withdrew the money from her bank and drove straight over. The next evening, punctually at seven o''clock, Rastus strolled home, looking plump, glossy, and thoroughly pleased with himself. Her friends were astounded when she told them the story. She only smiled and said that Rastus had always been dear to her. Considering the amount she had paid, he was now dear in more ways than one!","explanation_cn":"课文说 looking plump, glossy, and thoroughly pleased with himself——回家时又胖又得意。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l20',3,4,20,'Pioneer Pilots','飞行员的先驱','综合复习课:把前面学过的难点放在一起复习——happen to / it happened that(碰巧)、否定词句首倒装(Not only had he… / Never had…)、否定前缀(im-/ir-/dis-/un-/in-/il-)、be supposed to(本应)、would rather + 某人 + 过去式、had better、save up、find sb to be(原创承载 NCE3 L20 复习课·无需净化·1909年飞越英吉利海峡的竞赛:拉塔姆两次落海,布莱里奥37分钟成功横渡)','1908年,一位富有的报业主悬赏一千英镑,奖给第一个飞越英吉利海峡的飞行员——那是横在英法之间的一道狭窄海面。一年多过去,才有人敢试。1909年7月19日清早,法国人于贝尔·拉塔姆驾着他的飞机“安托瓦内特”号从法国海岸起飞。他只飞了七英里,发动机突然熄火,被迫降落在海面上。飞机静静浮着,直到一艘过路的船把他救起。拉塔姆不肯轻易罢休。几天后,对手路易·布莱里奥也带着自己的小飞机来到海岸附近。布莱里奥从1905年起就一直在造飞机,这是他最新的一架。两人本应在7月25日一同起飞,看上去会有一场精彩的比赛。可那天早上,拉塔姆偏偏没能早早醒来。布莱里奥在黎明前做了一次短暂试飞,随后出发。他那次著名的飞行只用了三十七分钟。降落在多佛附近时,第一个迎接他的,是一名一脸惊讶的当地警察。布莱里奥不但赢得了奖金,还创造了历史——成为第一个驾机飞越海峡的人。','{"q":"Listen and answer — What was the name of the first plane to fly across the English Channel?","options":["Blériot''s ''No. XI''","The ''Antoinette''","The ''Dover''","The ''Calais''"],"answer_index":0}'::jsonb,'{"title":"综合复习:倒装 / 否定前缀 / be supposed to / had better","intro":"本课把前面几单元的难点串起来复习:①happen to do / It happened that…（碰巧）。②否定词(Not only / Never / Not until)放句首,主句要倒装,把 had / did 提到主语前面:Not only had he won…。③加否定前缀构成反义词:im-（impolite）、ir-（irregular）、dis-（disagree）、un-（unlocked）、in-（inaccurate）、il-（illegible）。④be supposed to（本应、理应）。⑤would rather + 某人 + 过去式(委婉愿望)。⑥had better（最好)、save up（攒钱)、find sb to be（发现某人是…）。","table":{"headers":["复习点","意思","例子"],"rows":[["happen to / it happened that","碰巧","Latham happened to be over the sea."],["Not only + had + 主语…","否定词句首倒装","Not only had he won the prize…"],["im-/ir-/dis-/un- 等前缀","构成反义词","polite→impolite, regular→irregular"],["be supposed to / had better","本应 / 最好","were supposed to fly / had better check"]]},"specialRules":[{"rule":"否定词(Not only / Never / Not until)放句首时,主句要倒装:把 had 或 did 提到主语前面(Not only had he… / Not until noon did he…)。","mark":"否定词句首 → 倒装"},{"rule":"不同的词用不同的否定前缀,要一个个记:im-（p/m 前)、ir-（r 前)、il-（l 前)、in-、un-、dis-。","mark":"im-/ir-/il-/in-/un-/dis-"},{"rule":"美式用词:airplane(英式 aeroplane)、gasoline/gas(英式 petrol)。本课已按美语写。","mark":"airplane / gasoline"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l20',1,NULL,'In 1908, a wealthy newspaper owner offered a prize of a thousand pounds to the first pilot who would fly across the English Channel, the narrow stretch of sea between England and France. More than a year passed before anyone dared to try.','1908年,一位富有的报业主悬赏一千英镑,奖给第一个飞越英吉利海峡的飞行员——那是横在英法之间的一道狭窄海面。一年多过去,才有人敢试。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l20',2,NULL,'Early on the morning of July 19th, 1909, a Frenchman named Hubert Latham took off from the French coast in his plane, the ''Antoinette.'' He had flown only seven miles when his engine suddenly failed, and he was forced to land on the water. The plane floated calmly until a passing ship picked him up.','1909年7月19日清早,法国人于贝尔·拉塔姆驾着他的飞机“安托瓦内特”号从法国海岸起飞。他只飞了七英里,发动机突然熄火,被迫降落在海面上。飞机静静浮着,直到一艘过路的船把他救起。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l20',3,NULL,'Latham did not give up easily. A few days later a rival, Louis Blériot, arrived near the coast with a small plane of his own. Blériot had been building airplanes since 1905, and this was his newest model.','拉塔姆不肯轻易罢休。几天后,对手路易·布莱里奥也带着自己的小飞机来到海岸附近。布莱里奥从1905年起就一直在造飞机,这是他最新的一架。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l20',4,NULL,'Both men were supposed to take off on July 25th, and it looked as if there would be an exciting race. That morning, however, Latham failed to wake up early enough. Blériot made a short test flight before dawn, then set off.','两人本应在7月25日一同起飞,看上去会有一场精彩的比赛。可那天早上,拉塔姆偏偏没能早早醒来。布莱里奥在黎明前做了一次短暂试飞,随后出发。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l20',5,NULL,'His famous flight lasted only thirty-seven minutes. When he landed near Dover, the first person to greet him was a surprised local policeman. Not only had Blériot won the prize, but he had also made history as the first pilot ever to fly a plane across the Channel.','他那次著名的飞行只用了三十七分钟。降落在多佛附近时,第一个迎接他的,是一名一脸惊讶的当地警察。布莱里奥不但赢得了奖金,还创造了历史——成为第一个驾机飞越海峡的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
