INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l20','take off','',NULL,'/teɪk ɔːf/','The plane took off from the French coast.','飞机从法国海岸起飞。','What time does your flight take off?','你的航班几点起飞?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l20','give up','',NULL,'/ɡɪv ʌp/','Latham did not give up easily.','拉塔姆不肯轻易罢休。','Never give up on your dream.','永远别放弃你的梦想。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l20','be supposed to','',NULL,'/bi səˈpoʊzd tə/','Both pilots were supposed to fly on the 25th.','两位飞行员本应在25号起飞。','You''re supposed to be here by noon.','你本应中午前到这儿。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l20','not only ... but also','',NULL,'/nɑːt ˈoʊnli/','Not only had he won, but he had also made history.','他不但赢了,还创造了历史。','She not only sings but also dances.','她不但会唱,还会跳。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp1','choice','{"stem":"\"Latham ___ to be flying over the sea when his engine failed.\"(“碰巧正在”)","options":["happened","happens","happening","happen"],"answer_index":0,"stem_cn":"拉塔姆发动机出故障时,碰巧正飞在海面上。","explanation_cn":"“碰巧正在做某事”用 happen to be doing,过去用 happened。✓ Latham happened to be flying over the sea. ✗ happen / happens / happening:这里要用过去式 happened。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp1','choice','{"stem":"\"It ___ that both pilots reached the coast on the same day.\"(It ___ that… “碰巧”)","options":["happens","happening","happen","happened"],"answer_index":3,"stem_cn":"碰巧两位飞行员同一天到了海岸。","explanation_cn":"“It happened that…”表示“碰巧……”,过去用 happened。✓ It happened that both pilots reached the coast. ✗ happen / happens / happening:要用 happened。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp1','choice','{"stem":"\"If you ___ to see Blériot''s plane, you''d find it very small.\"(与 if 连用,表“万一/碰巧”,用原形)","options":["happen","happens","happening","happened"],"answer_index":0,"stem_cn":"你要是碰巧见到布莱里奥的飞机,会发现它很小。","explanation_cn":"“if you happen to…”表示“你要是碰巧……”,和 if 连用用原形 happen。✓ If you happen to see the plane… ✗ happened / happens / happening:这里用原形 happen。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp2','choice','{"stem":"\"Not only ___ Blériot won the prize, but he also made history.\"(否定词句首,主句倒装)","options":["he had","had","has","did had"],"answer_index":1,"stem_cn":"布莱里奥不但赢了奖,还创造了历史。","explanation_cn":"Not only 放句首,主句要倒装,把 had 提到主语前面。✓ Not only had Blériot won the prize… ✗ has 时态不对;✗ he had 没倒装;✗ did had 形式错。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp2','choice','{"stem":"\"Never ___ a plane crossed the Channel before that day.\"(Never 句首,倒装)","options":["had","did has","has","it had"],"answer_index":0,"stem_cn":"那天之前,从没有飞机飞越过海峡。","explanation_cn":"Never 放句首,句子要倒装,把 had 提前。✓ Never had a plane crossed the Channel before. ✗ has 时态不对;✗ it had 没倒装;✗ did has 形式错。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp2','choice','{"stem":"\"Not until noon ___ Latham realize he had overslept.\"(Not until 句首,倒装)","options":["he did","did","was","had"],"answer_index":1,"stem_cn":"直到中午,拉塔姆才意识到自己睡过了头。","explanation_cn":"Not until 放句首,主句要倒装,把 did 提到主语前面。✓ Not until noon did Latham realize… ✗ was 搭配不上;✗ he did 没倒装;✗ had 与后面 realize 不搭。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp3','choice','{"stem":"\"The opposite of ''polite'' is ___.\"(用哪个否定前缀)","options":["inpolite","unpolite","impolite","dispolite"],"answer_index":2,"stem_cn":"polite 的反义词。","explanation_cn":"polite 的反义词加前缀 im-（p 前用 im-）。✓ impolite. ✗ unpolite / dispolite / inpolite:polite 固定用 im-。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp3','choice','{"stem":"\"The opposite of ''regular'' is ___.\"(用哪个否定前缀)","options":["irregular","unregular","disregular","imregular"],"answer_index":0,"stem_cn":"regular 的反义词。","explanation_cn":"regular 的反义词加前缀 ir-（r 前用 ir-）。✓ irregular. ✗ unregular / disregular / imregular:regular 固定用 ir-。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp3','choice','{"stem":"\"The opposite of ''agree'' is ___.\"(用哪个否定前缀)","options":["unagree","inagree","disagree","imagree"],"answer_index":2,"stem_cn":"agree 的反义词。","explanation_cn":"agree 的反义词加前缀 dis-。✓ disagree. ✗ unagree / inagree / imagree:agree 固定用 dis-。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp4','choice','{"stem":"\"Both pilots ___ to take off on July 25th.\"(be supposed to:“本应”)","options":["supposed","were supposed","was supposed","are supposed"],"answer_index":1,"stem_cn":"两位飞行员本应在7月25日起飞。","explanation_cn":"“本应、理应”用 be supposed to;两人作主语,过去用 were supposed。✓ Both pilots were supposed to take off. ✗ are supposed 现在;✗ supposed 缺 be;✗ was supposed 单复数不对。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp4','choice','{"stem":"\"You are ___ to arrive before dawn, not after.\"(表“本应、理应”的固定说法)","options":["suppose","supposing","supposes","supposed"],"answer_index":3,"stem_cn":"你本应在黎明前到,而不是之后。","explanation_cn":"be supposed to“本应”,are 后面用过去分词 supposed。✓ You are supposed to arrive before dawn. ✗ suppose / supposing / supposes:固定用 supposed。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp4','choice','{"stem":"\"The judge would rather Latham ___ up earlier that morning.\"(would rather + 某人 + 过去式)","options":["wake","wakes","woke","to wake"],"answer_index":2,"stem_cn":"裁判宁愿拉塔姆那天早上早点醒。","explanation_cn":"would rather + 某人 + 过去式(委婉愿望),用过去式 woke。✓ would rather Latham woke up earlier. ✗ wakes / wake / to wake:这个句式里要用过去式 woke。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp5','choice','{"stem":"\"You ___ check the engine before you take off.\"(“最好”忠告)","options":["had better","better had","had to better","would better"],"answer_index":0,"stem_cn":"起飞前你最好检查一下发动机。","explanation_cn":"“最好…”的忠告用 had better + 动词原形。✓ You had better check the engine. ✗ would better / better had / had to better:固定说 had better。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp5','choice','{"stem":"\"If Blériot could ___ enough money, he would build a better plane.\"(短语动词“攒钱”)","options":["save in","save on","save up","save off"],"answer_index":2,"stem_cn":"布莱里奥要是能攒够钱,就会造更好的飞机。","explanation_cn":"“攒钱”用短语动词 save up。✓ save up enough money. ✗ save on / save off / save in:搭配不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp5','choice','{"stem":"\"Reporters found Blériot ___ a modest, quiet man.\"(find sb 后接不定式)","options":["be","to be","is","being"],"answer_index":1,"stem_cn":"记者们发现布莱里奥是个谦逊安静的人。","explanation_cn":"find + 某人 + to be…,后接不定式 to be。✓ found Blériot to be a modest man. ✗ being / is / be:find sb 后接 to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp6','choice','{"stem":"\"A person who is among the first to do something new is a ___.\"(“先驱”用哪个词)","options":["passenger","painter","prisoner","pioneer"],"answer_index":3,"stem_cn":"最早去做某件新事的人是先驱。","explanation_cn":"最早去做某件新事的人是 pioneer(先驱)。✓ pioneer pilots. ✗ passenger 乘客;✗ prisoner 囚犯;✗ painter 画家——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp6','choice','{"stem":"\"Traveling across land, not over water or air, is ___ travel.\"(“陆上的”用哪个词)","options":["overnight","overland","overhead","underwater"],"answer_index":1,"stem_cn":"走陆路而非水路或空路的旅行。","explanation_cn":"走陆路(而非水路、空路)的是 overland(陆上的)。✓ an overland flight. ✗ underwater 水下;✗ overhead 头顶;✗ overnight 过夜——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',5,'am3_l20_gp6','choice','{"stem":"\"To welcome someone when they arrive is to ___ them.\"(“迎接”用哪个词)","options":["chase","scold","greet","ignore"],"answer_index":2,"stem_cn":"有人到达时去欢迎他。","explanation_cn":"有人到达时去欢迎他用 greet(迎接)。✓ the first person to greet him. ✗ ignore 忽视;✗ chase 追赶;✗ scold 责备——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"pioneer 的意思是:","options":["先驱,开拓者","囚犯","乘客","画家"],"answer_index":0,"explanation_cn":"pioneer = 先驱、开拓者。✓ pioneer pilots 飞行先驱。\n顺带记:乘客 = passenger;囚犯 = prisoner;画家 = painter."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"attempt 的意思是:","options":["休息","尝试","放弃","成功"],"answer_index":1,"explanation_cn":"attempt = 尝试、试图。✓ the first attempt 第一次尝试。\n顺带记:放弃 = give up;成功 = success;休息 = rest."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"engine 的意思是:","options":["座位","轮子","机翼","发动机,引擎"],"answer_index":3,"explanation_cn":"engine = 发动机、引擎。✓ his engine failed 他的发动机熄火了。\n顺带记:机翼 = wing;轮子 = wheel;座位 = seat."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"rival 的意思是:","options":["竞争对手","教练","伙伴","观众"],"answer_index":0,"explanation_cn":"rival = 竞争对手。✓ a rival, Louis Blériot 对手路易·布莱里奥。\n顺带记:伙伴 = partner;教练 = coach;观众 = audience."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"greet 的意思是:","options":["追赶","忽视","迎接,问候","责备"],"answer_index":2,"explanation_cn":"greet = 迎接、问候。✓ the first person to greet him 第一个迎接他的人。\n顺带记:忽视 = ignore;追赶 = chase;责备 = scold."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',6,NULL,'choice','{"stem":"overland 的意思是:","options":["陆上的","头顶的","夜间的","水下的"],"answer_index":0,"explanation_cn":"overland = 陆上的(走陆路)。✓ an overland flight 陆上飞行。\n顺带记:水下的 = underwater;头顶的 = overhead;夜间的 = overnight."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',7,NULL,'cloze','{"stem":"第 1 空","context":"Both pilots ___1___ supposed to take off on July 25th. That morning, however, Latham failed to wake up. Blériot flew across in only thirty-seven minutes. ___2___ only had he won the prize, but he had also made history. Reporters found him ___3___ be a modest man. If a young pilot wants to fly the Channel today, he ___4___ better prepare well first.","blank_no":1,"options":["were","are","was","being"],"answer_index":0,"explanation_cn":"be supposed to,两人作主语,过去用 were。✓ Both pilots were supposed to take off."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',7,NULL,'cloze','{"stem":"第 2 空","context":"Both pilots ___1___ supposed to take off on July 25th. That morning, however, Latham failed to wake up. Blériot flew across in only thirty-seven minutes. ___2___ only had he won the prize, but he had also made history. Reporters found him ___3___ be a modest man. If a young pilot wants to fly the Channel today, he ___4___ better prepare well first.","blank_no":2,"options":["Not","No","Never","None"],"answer_index":0,"explanation_cn":"Not only 放句首引出倒装。✓ Not only had he won the prize, but he had also made history."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',7,NULL,'cloze','{"stem":"第 3 空","context":"Both pilots ___1___ supposed to take off on July 25th. That morning, however, Latham failed to wake up. Blériot flew across in only thirty-seven minutes. ___2___ only had he won the prize, but he had also made history. Reporters found him ___3___ be a modest man. If a young pilot wants to fly the Channel today, he ___4___ better prepare well first.","blank_no":3,"options":["to","being","is","be"],"answer_index":0,"explanation_cn":"find + 某人 + to be…,用不定式 to。✓ Reporters found him to be a modest man."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',7,NULL,'cloze','{"stem":"第 4 空","context":"Both pilots ___1___ supposed to take off on July 25th. That morning, however, Latham failed to wake up. Blériot flew across in only thirty-seven minutes. ___2___ only had he won the prize, but he had also made history. Reporters found him ___3___ be a modest man. If a young pilot wants to fly the Channel today, he ___4___ better prepare well first.","blank_no":4,"options":["had","would","has","have"],"answer_index":0,"explanation_cn":"“最好…”的忠告用 had better。✓ he had better prepare well first."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',8,NULL,'choice','{"stem":"What prize was offered to the first pilot to fly across the Channel?","options":["A gold medal","A thousand pounds","A house in Dover","A brand-new plane"],"answer_index":1,"explanation_cn":"课文说 offered a prize of a thousand pounds——悬赏一千英镑。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',8,NULL,'choice','{"stem":"Why did Latham fail on July 25th?","options":["His plane caught fire","He lost his way","He ran out of fuel","He did not wake up early enough"],"answer_index":3,"explanation_cn":"课文说 Latham failed to wake up early enough——那天早上他没能早醒,所以失败。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',8,NULL,'choice','{"stem":"Who was the first to greet Blériot when he landed?","options":["A local policeman","The mayor of Dover","A newspaper reporter","His wife"],"answer_index":0,"explanation_cn":"课文说 the first person to greet him was a surprised local policeman——第一个迎接他的是当地警察。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',9,NULL,'choice','{"stem":"你想说\"两位飞行员本应在25号起飞\"(be supposed to):","options":["Both pilots were suppose to take off on the 25th.","Both pilots supposed to take off on the 25th.","Both pilots are supposed to take off on the 25th.","Both pilots were supposed to take off on the 25th."],"answer_index":3,"explanation_cn":"“本应”用 be supposed to;过去、两人用 were supposed。✓ Both pilots were supposed to take off on the 25th. 场合:说某事本来该怎样(但没发生)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',9,NULL,'choice','{"stem":"你想说\"他不但赢了奖,还创造了历史\"(否定词句首倒装):","options":["Not only had he won the prize, but he had also made history.","Not only he won the prize, but also made history.","Not only he had won the prize, but he had also made history.","Not only won he the prize, but he had also made history."],"answer_index":0,"explanation_cn":"Not only 放句首,主句倒装,把 had 提前。✓ Not only had he won the prize, but he had also made history. 场合:强调“不但…而且…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',9,NULL,'choice','{"stem":"你想说\"起飞前你最好检查一下发动机\"(had better):","options":["You had better to check the engine before takeoff.","You had better check the engine before takeoff.","You would better check the engine before takeoff.","You had best checking the engine before takeoff."],"answer_index":1,"explanation_cn":"“最好…”用 had better + 动词原形。✓ You had better check the engine before takeoff. 场合:强烈建议某人做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"pioneer 的意思是:","options":["囚犯","画家","先驱,开拓者","乘客"],"answer_index":2,"explanation_cn":"pioneer = 先驱、开拓者。✓ pioneer pilots."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"greet 的意思是:","options":["责备","迎接,问候","追赶","忽视"],"answer_index":1,"explanation_cn":"greet = 迎接、问候。✓ the first person to greet him."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"\"Both pilots ___ supposed to take off on the 25th.\"(be supposed to)","options":["were","are","being","was"],"answer_index":0,"stem_cn":"两位飞行员本应在25号起飞。","explanation_cn":"be supposed to,两人作主语,过去用 were。✓ Both pilots were supposed to take off. ✗ are 现在;✗ was 单复数不对;✗ being 缺谓语。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"\"Not only ___ he won the prize, but he also made history.\"(否定词句首倒装)","options":["he had","had","has","did had"],"answer_index":1,"stem_cn":"他不但赢了奖,还创造了历史。","explanation_cn":"Not only 放句首,主句倒装,把 had 提前。✓ Not only had he won the prize… ✗ has 时态不对;✗ he had 没倒装;✗ did had 形式错。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"\"give up\" 的意思是:","options":["追上","举起","放弃","分发"],"answer_index":2,"explanation_cn":"give up = 放弃。✓ did not give up easily 不轻易放弃。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"\"take off\"(飞机)的意思是:","options":["起飞","转弯","加速","降落"],"answer_index":0,"explanation_cn":"take off(飞机)= 起飞。✓ took off from the coast 从海岸起飞。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"Who finally flew across the Channel first?","options":["A policeman","Hubert Latham","The newspaper owner","Louis Blériot"],"answer_index":3,"passage":"In 1908, a wealthy newspaper owner offered a prize of a thousand pounds to the first pilot who would fly across the English Channel, the narrow stretch of sea between England and France. More than a year passed before anyone dared to try. Early on the morning of July 19th, 1909, a Frenchman named Hubert Latham took off from the French coast in his plane, the ''Antoinette.'' He had flown only seven miles when his engine suddenly failed, and he was forced to land on the water. The plane floated calmly until a passing ship picked him up. Latham did not give up easily. A few days later a rival, Louis Blériot, arrived near the coast with a small plane of his own. Blériot had been building airplanes since 1905, and this was his newest model. Both men were supposed to take off on July 25th, and it looked as if there would be an exciting race. That morning, however, Latham failed to wake up early enough. Blériot made a short test flight before dawn, then set off. His famous flight lasted only thirty-seven minutes. When he landed near Dover, the first person to greet him was a surprised local policeman. Not only had Blériot won the prize, but he had also made history as the first pilot ever to fly a plane across the Channel.","explanation_cn":"课文说 Blériot…the first pilot ever to fly a plane across the Channel——最先飞越海峡的是布莱里奥。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"What happened to Latham on his first attempt?","options":["He reached Dover safely","He never took off","His engine failed and he landed on the sea","He won the prize"],"answer_index":2,"passage":"In 1908, a wealthy newspaper owner offered a prize of a thousand pounds to the first pilot who would fly across the English Channel, the narrow stretch of sea between England and France. More than a year passed before anyone dared to try. Early on the morning of July 19th, 1909, a Frenchman named Hubert Latham took off from the French coast in his plane, the ''Antoinette.'' He had flown only seven miles when his engine suddenly failed, and he was forced to land on the water. The plane floated calmly until a passing ship picked him up. Latham did not give up easily. A few days later a rival, Louis Blériot, arrived near the coast with a small plane of his own. Blériot had been building airplanes since 1905, and this was his newest model. Both men were supposed to take off on July 25th, and it looked as if there would be an exciting race. That morning, however, Latham failed to wake up early enough. Blériot made a short test flight before dawn, then set off. His famous flight lasted only thirty-seven minutes. When he landed near Dover, the first person to greet him was a surprised local policeman. Not only had Blériot won the prize, but he had also made history as the first pilot ever to fly a plane across the Channel.","explanation_cn":"课文说 his engine suddenly failed, and he was forced to land on the water——第一次尝试时他发动机熄火,迫降海面。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"How long did Blériot''s famous flight last?","options":["Two hours","A whole day","Seven minutes","Thirty-seven minutes"],"answer_index":3,"audio":"In 1908, a wealthy newspaper owner offered a prize of a thousand pounds to the first pilot who would fly across the English Channel, the narrow stretch of sea between England and France. More than a year passed before anyone dared to try. Early on the morning of July 19th, 1909, a Frenchman named Hubert Latham took off from the French coast in his plane, the ''Antoinette.'' He had flown only seven miles when his engine suddenly failed, and he was forced to land on the water. The plane floated calmly until a passing ship picked him up. Latham did not give up easily. A few days later a rival, Louis Blériot, arrived near the coast with a small plane of his own. Blériot had been building airplanes since 1905, and this was his newest model. Both men were supposed to take off on July 25th, and it looked as if there would be an exciting race. That morning, however, Latham failed to wake up early enough. Blériot made a short test flight before dawn, then set off. His famous flight lasted only thirty-seven minutes. When he landed near Dover, the first person to greet him was a surprised local policeman. Not only had Blériot won the prize, but he had also made history as the first pilot ever to fly a plane across the Channel.","explanation_cn":"课文说 His famous flight lasted only thirty-seven minutes——那次飞行只用了37分钟。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l20',10,NULL,'choice','{"stem":"How did Latham react to his first failure?","options":["He moved to England","He sold his plane","He did not give up easily","He gave up flying for good"],"answer_index":2,"audio":"In 1908, a wealthy newspaper owner offered a prize of a thousand pounds to the first pilot who would fly across the English Channel, the narrow stretch of sea between England and France. More than a year passed before anyone dared to try. Early on the morning of July 19th, 1909, a Frenchman named Hubert Latham took off from the French coast in his plane, the ''Antoinette.'' He had flown only seven miles when his engine suddenly failed, and he was forced to land on the water. The plane floated calmly until a passing ship picked him up. Latham did not give up easily. A few days later a rival, Louis Blériot, arrived near the coast with a small plane of his own. Blériot had been building airplanes since 1905, and this was his newest model. Both men were supposed to take off on July 25th, and it looked as if there would be an exciting race. That morning, however, Latham failed to wake up early enough. Blériot made a short test flight before dawn, then set off. His famous flight lasted only thirty-seven minutes. When he landed near Dover, the first person to greet him was a surprised local policeman. Not only had Blériot won the prize, but he had also made history as the first pilot ever to fly a plane across the Channel.","explanation_cn":"课文说 Latham did not give up easily——第一次失败后他没有轻易放弃。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
